"""matplotlib.axes — Axes classes."""

from matplotlib.axes._axes import Axes, SubplotBase, Subplot


def subplot_class_factory(axes_class=None):
    """Upstream synthesises a Subplot subclass that adds row/col tracking
    onto a given ``axes_class``. The shim's :class:`Axes` already does
    the tracking, so we just return it (or a trivial subclass when an
    alternate ``axes_class`` is supplied).
    """
    if axes_class is None or axes_class is Axes:
        return Subplot
    # Mint a subclass that inherits from the requested axes_class plus
    # SubplotBase so isinstance checks against both pass.
    name = f'Subplot{axes_class.__name__}'
    return type(name, (axes_class, SubplotBase), {})


__all__ = ['Axes', 'SubplotBase', 'Subplot', 'subplot_class_factory']
